class Solution {
    public int peakIndexInMountainArray(int[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < arr[mid + 1]) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public int peakIndexInMountainArray(int[] arr) {
        int left = 1;
        int right = arr.length - 2;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] > arr[mid - 1] && arr[mid] > arr[mid + 1]) {
                return mid;
            }
            if (arr[mid] < arr[mid + 1]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
}

class Solution {
    public int peakIndexInMountainArray(int[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (right - left > 3) {
            int third = (right - left) / 3;
            int mid1 = left + third;
            int mid2 = right - third;
            if (arr[mid1] < arr[mid2]) {
                left = mid1 + 1;
            } else {
                right = mid2 - 1;
            }
        }
        int best = left;
        for (int i = left + 1; i <= right; i++) {
            if (arr[i] > arr[best]) {
                best = i;
            }
        }
        return best;
    }
}

class Solution {
    public int peakIndexInMountainArray(int[] arr) {
        return search(arr, 0, arr.length - 1);
    }

    private int search(int[] arr, int left, int right) {
        if (left == right) {
            return left;
        }
        int mid = left + (right - left) / 2;
        if (arr[mid] < arr[mid + 1]) {
            return search(arr, mid + 1, right);
        }
        return search(arr, left, mid);
    }
}
